  "D.01.5.1": { lamaIndikator: "Pernyataan VMTS yang unik dan spesifik sebagai identitas PT, UPPS, dan visi keilmuan program studi sebagai keunggulan kompetitif yang didukung dengan renstra dan kurikulum yang memadai.", lamaUraian: "Pernyataan VMTS yang unik dan spesifik sebagai identitas PT, UPPS, dan visi keilmuan program studi sebagai keunggulan kompetitif yang didukung dengan renstra dan kurikulum yang memadai.", refItemId: 208, baru: "Kekhasan pernyataan VMTS sebagai identitas PT, UPPS, dan visi keilmuan program studi diploma III, didukung renstra dan kurikulum yang memadai, mencakup linearitas visi PT ke VMTS UPPS, kesesuaian VMTS dengan renstra, kesesuaian visi keilmuan dengan kurikulum, serta tinjauan berkala." },
  "D.01.5.2": { lamaIndikator: "Mekanisme dan keterlibatan pemangku kepentingan dalam penyusunan VMTS UPPS dan tujuan utama yang ingin dicapai dalam penyusunan visi keilmuan program studi dengan mempertimbangkan kebutuhan masyarakat dan tantangan global.", lamaUraian: "Mekanisme dan keterlibatan pemangku kepentingan dalam penyusunan VMTS UPPS dan tujuan utama yang ingin dicapai dalam penyusunan visi keilmuan program studi dengan mempertimbangkan kebutuhan masyarakat dan tantangan global.", refItemId: 209, baru: "Mekanisme dan keterlibatan pemangku kepentingan internal (dosen, mahasiswa, tenaga kependidikan) dan eksternal (lulusan, pengguna lulusan, pakar) dalam penyusunan VMTS UPPS dan visi keilmuan program studi diploma III." },
  "D.01.5.3": { lamaIndikator: "Tingkat pemahaman dan pencapaian VMTS UPPS dan visi keilmuan program studi oleh seluruh pemangku kepentingan internal dan eksternal serta pencapaian konkret jangka pendek dan jangka menengah yang telah ditetapkan dalam VMTS UPPS dan visi keilmuan program studi.", lamaUraian: "Tingkat pemahaman dan pencapaian VMTS UPPS dan visi keilmuan program studi oleh seluruh pemangku kepentingan internal dan eksternal serta pencapaian konkret jangka pendek dan jangka menengah yang telah ditetapkan dalam VMTS UPPS dan visi keilmuan program studi.", refItemId: 210, baru: "Tingkat pemahaman dan pencapaian VMTS UPPS dan visi keilmuan program studi diploma III oleh seluruh pemangku kepentingan internal dan eksternal, termasuk pencapaian konkret jangka pendek dan jangka menengah yang telah ditetapkan." },
  "D.02.6.1": { lamaIndikator: "Kelengkapan struktur organisasi dan kebijakan operasional yang berpedoman pada statuta Perguruan Tinggi yang digunakan.", lamaUraian: "Kelengkapan struktur organisasi dan kebijakan operasional yang berpedoman pada statuta Perguruan Tinggi yang digunakan.", refItemId: 213, baru: "Kelengkapan struktur organisasi dan kebijakan operasional UPPS pada program studi diploma III, berpedoman pada statuta PKTJ, mencakup kewenangan dan tugas yang dijalankan efektif serta aras kewenangan organ pokok." },
  "D.02.6.2": { lamaIndikator: "Perwujudan Good University Governance mengacu pada sistem tata kelola yang efektif, transparan, dan akuntabel.", lamaUraian: "Perwujudan Good University Governance mengacu pada sistem tata kelola yang efektif, transparan, dan akuntabel.", refItemId: 214, baru: "Perwujudan Good University Governance pada UPPS program studi diploma III, mengacu pada sistem tata kelola yang efektif, transparan, dan akuntabel." },
  "D.02.6.3": { lamaIndikator: "Pimpinan UPPS memiliki komitmen pada: (1) Visi dan tujuan organisasi; (2) Integritas dan transparansi; (3) Pengembangan sumber daya.", lamaUraian: "Pimpinan UPPS memiliki komitmen pada: (1) Visi dan tujuan organisasi; (2) Integritas dan transparansi; (3) Pengembangan sumber daya.", refItemId: 215, baru: "Komitmen pimpinan UPPS program studi diploma III pada visi dan tujuan organisasi, integritas dan transparansi, serta pengembangan sumber daya." },
